// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, c.MinDeposit(), 1000 ether);
        Log log = Log(address(0));
        // History is a public array getter: c.TransferLog() gives the Log address
        log = Log(c.TransferLog());
        uint256 before = log.History(0) == log.History(0) ? 0 : 0; // placeholder avoided below
        // read length via public getter pattern: History(uint) has no length getter, so count via
        // probing is wasteful; instead track by calling History on an out-of-range index in try/catch.
        uint256 lenBefore = 0;
        while (true) {
            try log.History(lenBefore) returns (Log.Message memory) {
                lenBefore++;
            } catch {
                break;
            }
        }
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        uint256 lenAfter = 0;
        while (true) {
            try log.History(lenAfter) returns (Log.Message memory) {
                lenAfter++;
            } catch {
                break;
            }
        }
        assertTrue(lenAfter == lenBefore + 1);
    }
}

